    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(a > 0);
        require(address(this).balance >= a);
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        uint cBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && cBefore - address(c).balance == a && address(this).balance - thisBefore == a);
    }
    receive() external payable {}
}

